// Parse openFDA label response and extract relevant fields
const items = $input.all();
const parsed = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const results = body.results || [];

  for (const label of results) {
    const openfda = label.openfda || {};
    parsed.push({
      json: {
        drug_name: (openfda.generic_name || ['unknown'])[0].toLowerCase(),
        brand_names: (openfda.brand_name || []).map(b => b.toLowerCase()),
        spl_id: label.id || null,
        indications: (label.indications_and_usage || [''])[0].substring(0, 2000),
        warnings: (label.warnings || [''])[0].substring(0, 2000),
        drug_interactions: (label.drug_interactions || [''])[0].substring(0, 2000),
        dosage_and_administration: (label.dosage_and_administration || [''])[0].substring(0, 2000),
        contraindications: (label.contraindications || [''])[0].substring(0, 2000),
        adverse_reactions: (label.adverse_reactions || [''])[0].substring(0, 2000),
        active_ingredient: (label.active_ingredient || [''])[0].substring(0, 500),
        route: (openfda.route || []),
        product_type: (openfda.product_type || []),
        manufacturer: (openfda.manufacturer_name || []),
        effective_time: label.effective_time || null
      }
    });
  }
}

return parsed.length > 0 ? parsed : [{ json: { _empty: true } }];

// Clean and normalize data for PredictRx ingestion
const items = $input.all();
const cleaned = [];

for (const item of items) {
  const d = item.json;

  // Skip if no drug_name
  if (!d.drug_name || d.drug_name === 'unknown') continue;

  // Normalize text fields: trim, collapse whitespace, remove control chars
  const cleanText = (text) => {
    if (!text) return '';
    return text
      .replace(/[\x00-\x1F\x7F]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  };

  cleaned.push({
    json: {
      generic_name: d.drug_name.trim().toLowerCase(),
      brand_names: d.brand_names || [],
      spl_id: d.spl_id,
      indications: cleanText(d.indications),
      warnings: cleanText(d.warnings),
      drug_interactions: cleanText(d.drug_interactions),
      dosage_and_administration: cleanText(d.dosage_and_administration),
      contraindications: cleanText(d.contraindications),
      adverse_reactions: cleanText(d.adverse_reactions),
      active_ingredient: cleanText(d.active_ingredient),
      route: d.route,
      product_type: d.product_type,
      manufacturer: d.manufacturer,
      effective_time: d.effective_time,
      _ingested_at: new Date().toISOString(),
      _source: 'openfda_label_api'
    }
  });
}

return cleaned.length > 0 ? cleaned : [{ json: { _skipped: true, reason: 'all records empty after cleaning' } }];

// Build summary of the pipeline run
const loadOutput = $('Run load.py').first().json;
const reportOutput = $('Run report.py').first().json;

const summary = {
  pipeline: 'PredictRx Data Ingestion',
  completed_at: new Date().toISOString(),
  load_result: {
    stdout: loadOutput.stdout || '',
    stderr: loadOutput.stderr || '',
    exitCode: loadOutput.exitCode
  },
  report_result: {
    stdout: reportOutput.stdout || '',
    stderr: reportOutput.stderr || '',
    exitCode: reportOutput.exitCode
  },
  status: (loadOutput.exitCode === 0 && reportOutput.exitCode === 0) ? 'SUCCESS' : 'FAILED'
};

return [{ json: summary }];
